-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Validates only the fields consumed by the group UI, with a fixed row budget.
-- Never walk arbitrary received tables: unknown fields are discarded after deserialization.

APR.PartyProtocol = {}
local protocol = APR.PartyProtocol
local MAX_INDEX, MAX_ROWS = 1000000, 128
local ROUTE_FIELDS = { "route", "routeFileName" }
local PROGRESS_FIELDS = { "index", "step", "total" }
local DETAIL_FIELDS = { "extraLines", "questSteps", "fillerSteps" }

local function IsInteger(value, minimum)
    return type(value) == "number" and value == value and value >= minimum
        and value <= MAX_INDEX and value % 1 == 0
end--[[APR_DIAG]]; IsInteger = APRTrace("APR-Core/features/group/PartyProtocol.lua:16:IsInteger#1", IsInteger)--[[/APR_DIAG]]

local function StripHyperlinkMarkup(value)
    local parts, cursor = nil, 1
    while true do
        local first = value:find("|H", cursor, true)
        if not first then break end
        local label = value:find("|h", first + 2, true)
        local last = label and value:find("|h", label + 2, true)
        -- With fewer than two closing delimiters left, no later opener can
        -- form a complete link. Preserve the unmatched suffix without rescans.
        if not last then break end
        parts = parts or {}
        parts[#parts + 1] = value:sub(cursor, first - 1)
        parts[#parts + 1] = value:sub(label + 2, last - 1)
        cursor = last + 2
    end
    if not parts then return value end
    parts[#parts + 1] = value:sub(cursor)
    return table.concat(parts)
end--[[APR_DIAG]]; StripHyperlinkMarkup = APRTrace("APR-Core/features/group/PartyProtocol.lua:21:StripHyperlinkMarkup#2", StripHyperlinkMarkup)--[[/APR_DIAG]]

local function StripArtMarkup(value)
    local parts, cursor = nil, 1
    while true do
        local first = value:find("|[TA]", cursor)
        if not first then break end
        local last = value:find("|[ta]", first + 2)
        if not last then break end
        parts = parts or {}
        parts[#parts + 1] = value:sub(cursor, first - 1)
        cursor = last + 2
    end
    if not parts then return value end
    parts[#parts + 1] = value:sub(cursor)
    return table.concat(parts)
end--[[APR_DIAG]]; StripArtMarkup = APRTrace("APR-Core/features/group/PartyProtocol.lua:41:StripArtMarkup#3", StripArtMarkup)--[[/APR_DIAG]]

local function Text(value, limit)
    if type(value) ~= "string" or #value > limit then return nil end
    -- Tooltip text is data, never texture/atlas instructions supplied by another player.
    -- Non-greedy unanchored patterns retry at every unmatched opener, turning
    -- a bounded but malformed peer snapshot into quadratic work on one frame.
    if value:find("|", 1, true) then
        value = StripHyperlinkMarkup(value)
        value = StripArtMarkup(value)
        value = value:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
    end
    return value:gsub("[%z\1-\8\11\12\14-\31]", "")
end--[[APR_DIAG]]; Text = APRTrace("APR-Core/features/group/PartyProtocol.lua:57:Text#4", Text)--[[/APR_DIAG]]

local function NameParts(value)
    if type(value) ~= "string" or #value == 0 or #value > 128 or value:find("[%c|]") then return end
    local name, realm = value:match("^([^%-]+)%-(.+)$")
    return name or value, realm and realm:gsub("%s", "")
end--[[APR_DIAG]]; NameParts = APRTrace("APR-Core/features/group/PartyProtocol.lua:70:NameParts#5", NameParts)--[[/APR_DIAG]]

function protocol.PlayerKey(value)
    local name, realm = NameParts(value)
    if not name then return end
    local home = GetNormalizedRealmName and GetNormalizedRealmName() or GetRealmName and GetRealmName() or ""
    return name .. "-" .. (realm or home:gsub("%s", ""))
end--[[APR_DIAG]]; protocol.PlayerKey = APRTrace("APR-Core/features/group/PartyProtocol.lua:76:protocol.PlayerKey#6", protocol.PlayerKey)--[[/APR_DIAG]]

function protocol.DisplayName(value)
    local name, realm = NameParts(value)
    if not name then return end
    local home = GetNormalizedRealmName and GetNormalizedRealmName() or GetRealmName and GetRealmName() or ""
    return realm and realm ~= home:gsub("%s", "") and (name .. "-" .. realm) or name
end--[[APR_DIAG]]; protocol.DisplayName = APRTrace("APR-Core/features/group/PartyProtocol.lua:83:protocol.DisplayName#7", protocol.DisplayName)--[[/APR_DIAG]]

-- Sender is authoritative. Legacy peers may send only a character name in their payload.
function protocol.NormalizeSnapshot(data, sender)
    if type(data) ~= "table" then return nil, "payload_type" end
    local name, realm = NameParts(sender)
    local claimed, claimedRealm = NameParts(data.username)
    if not name or claimed ~= name or (claimedRealm and protocol.PlayerKey(data.username) ~= protocol.PlayerKey(sender)) then
        return nil, "sender_mismatch"
    end
    local result = { username = protocol.DisplayName(sender), sender = protocol.PlayerKey(sender) }
    for _, field in ipairs(ROUTE_FIELDS) do
        if data[field] ~= nil then
            result[field] = Text(data[field], 256)
            if not result[field] then return nil, "route_type" end
        end
    end
    if data.sojournerSkipCampaign ~= nil and type(data.sojournerSkipCampaign) ~= "boolean" then return nil, "campaign_type" end
    result.sojournerSkipCampaign = data.sojournerSkipCampaign == true
    if data.currentStep ~= nil and not IsInteger(data.currentStep, 0) then return nil, "step_range" end
    if data.totalSteps ~= nil and not IsInteger(data.totalSteps, 0) then return nil, "total_range" end
    if data.currentStep and data.totalSteps and data.totalSteps > 0 and data.currentStep > data.totalSteps + 1 then
        return nil, "progress_range"
    end
    result.currentStep, result.totalSteps = data.currentStep, data.totalSteps
    if data.routeProgress ~= nil then
        local progress = data.routeProgress
        if type(progress) ~= "table" or type(progress.id) ~= "string" or #progress.id > 64
            or not IsInteger(progress.step, 1) or not IsInteger(progress.total, 1)
            or progress.step > progress.total + 1 then return nil, "route_progress" end
        local mainIndex = progress.id:match("^main:(%d+)$")
        local group, index = progress.id:match("^parallel:(%d+):(%d+)$")
        local valid = mainIndex and tonumber(mainIndex) == progress.step and progress.step <= progress.total
            or group and IsInteger(tonumber(group), 1) and IsInteger(tonumber(index), 1)
            or progress.id == "end" and progress.step == progress.total + 1
        if not valid or not result.routeFileName then return nil, "route_progress" end
        result.routeProgress = { id = progress.id, step = progress.step, total = progress.total }
    end
    local details = data.stepFrameDetails
    if details == nil then return result end
    if type(details) ~= "table" then return nil, "details_type" end
    result.stepFrameDetails = {}
    if details.progress ~= nil then
        if type(details.progress) ~= "table" then return nil, "progress_type" end
        local progress = {}
        for _, field in ipairs(PROGRESS_FIELDS) do
            local value = details.progress[field]
            if value ~= nil and not IsInteger(value, 0) then return nil, "progress_range" end
            progress[field] = value
        end
        result.stepFrameDetails.progress = progress
    end
    local remaining = MAX_ROWS
    for _, field in ipairs(DETAIL_FIELDS) do
        local rows = details[field]
        if rows ~= nil then
            if type(rows) ~= "table" then return nil, "rows_type" end
            local clean = {}
            result.stepFrameDetails[field] = clean
            for index = 1, MAX_ROWS + 1 do
                local row = rows[index]
                if row == nil then break end
                remaining = remaining - 1
                if remaining < 0 or type(row) ~= "table" then return nil, "row_budget" end
                local text = Text(row.text, 1024)
                if not text then return nil, "row_text" end
                local entry = { text = text }
                clean[#clean + 1] = entry
                if row.subSteps ~= nil then
                    if type(row.subSteps) ~= "table" then return nil, "substeps_type" end
                    entry.subSteps = {}
                    for subIndex = 1, MAX_ROWS + 1 do
                        local sub = row.subSteps[subIndex]
                        if sub == nil then break end
                        remaining = remaining - 1
                        if remaining < 0 or type(sub) ~= "table" then return nil, "row_budget" end
                        local subText = Text(sub.text, 1024)
                        if not subText then return nil, "row_text" end
                        entry.subSteps[#entry.subSteps + 1] = { text = subText }
                    end
                end
            end
        end
    end
    return result
end--[[APR_DIAG]]; protocol.NormalizeSnapshot = APRTrace("APR-Core/features/group/PartyProtocol.lua:91:protocol.NormalizeSnapshot#8", protocol.NormalizeSnapshot)--[[/APR_DIAG]]

-- Compare consumed values before serialization or frame work. Metadata, filler
-- rows and duplicated effective indices never affect another player's display.
function protocol.SameProgress(a, b)
    if not a or not b then return false end
    if a.route ~= b.route or a.routeFileName ~= b.routeFileName
        or a.currentStep ~= b.currentStep or a.totalSteps ~= b.totalSteps then return false end
    local left, right = a.routeProgress, b.routeProgress
    if left == right then return true end
    return left ~= nil and right ~= nil and left.id == right.id
        and left.step == right.step and left.total == right.total
end--[[APR_DIAG]]; protocol.SameProgress = APRTrace("APR-Core/features/group/PartyProtocol.lua:177:protocol.SameProgress#9", protocol.SameProgress)--[[/APR_DIAG]]

local function SameRows(a, b)
    if a == b then return true end
    local count = a and #a or 0
    if count ~= (b and #b or 0) then return false end
    for index = 1, count do
        local left, right = a[index], b[index]
        if left.text ~= right.text then return false end
        local subCount = left.subSteps and #left.subSteps or 0
        if subCount ~= (right.subSteps and #right.subSteps or 0) then return false end
        for sub = 1, subCount do
            if left.subSteps[sub].text ~= right.subSteps[sub].text then return false end
        end
    end
    return true
end--[[APR_DIAG]]; SameRows = APRTrace("APR-Core/features/group/PartyProtocol.lua:187:SameRows#10", SameRows)--[[/APR_DIAG]]

function protocol.SameDetails(a, b)
    if a == b then return true end
    return SameRows(a and a.extraLines, b and b.extraLines)
        and SameRows(a and a.questSteps, b and b.questSteps)
end--[[APR_DIAG]]; protocol.SameDetails = APRTrace("APR-Core/features/group/PartyProtocol.lua:203:protocol.SameDetails#11", protocol.SameDetails)--[[/APR_DIAG]]
